import type {HandbookEntry} from './handbook-types';

const api=(name:string)=>'https://learn.microsoft.com/en-us/dotnet/api/'+name;
const lang=(path:string)=>'https://learn.microsoft.com/en-us/dotnet/csharp/'+path;
function e(id:string,title:string,category:string,kind:string,description:string,syntax:string,example:string,notes:string,docsUrl:string,lectureTokens:string[]=[],aliases:string[]=[]):HandbookEntry{return {id:'cs-'+id,title,category,kind,description,syntax,example,notes,docsUrl,lectureTokens,aliases};}
const basics='Основы C#';const oop='Классы и объекты';const strings='Строки и форматирование';const nums='Числа, даты и время';const collections='Коллекции и LINQ';const files='Файлы, ошибки и асинхронность';

export const csharpEntries:HandbookEntry[]=[
 e('is-pattern','is и is not — проверка типа',basics,'Оператор','Проверяет фактический тип значения и при совпадении позволяет получить типизированную переменную. Шаблон is not удобен для раннего отказа.','значение is Тип имя\nзначение is not Тип имя','object value = "Мяч";\nif (value is not string name)\n    return;\nConsole.WriteLine(name);','После раннего return переменная name доступна в оставшейся части метода. Проверка типа не преобразует текст "12" в число: для этого нужен TryParse.',lang('language-reference/operators/type-testing-and-cast'),['is not','is'],['проверка типа','сопоставление с образцом','pattern matching']),
 e('this','this — текущий объект',oop,'Ключевое слово','Обозначает экземпляр класса, внутри которого выполняется код. Помогает отличить поле от одноимённого параметра или передать текущий объект методу.','this.ИмяЧлена','public class NamedItem\n{\n    private string name;\n    public NamedItem(string name)\n    {\n        this.name = name;\n    }\n}','this нельзя использовать в static-методе: у него нет текущего экземпляра. Слева this.name — поле объекта, справа name — параметр конструктора.',lang('language-reference/keywords/this'),['this'],['текущий экземпляр','поле и параметр']),
 e('language','C#',basics,'Язык','Язык со строгой системой типов для описания данных и поведения программы. Компилятор проверяет код до запуска, а .NET предоставляет среду выполнения и библиотеки.','тип имя = значение;','int stock = 8;\nbool available = stock > 0;','C# — язык, .NET — платформа, Windows Forms — библиотека интерфейса. Это разные части приложения.',lang('tour-of-csharp/'),['C#'],['си шарп','csharp','язык программирования']),
 e('statement','Инструкция и точка с запятой',basics,'Синтаксис','Инструкция задаёт действие. Многие простые инструкции завершаются точкой с запятой; фигурные скобки объединяют инструкции в блок.','выражение;','int stock = 8;\nstock = stock - 1;','После закрывающей скобки обычного блока if или метода точка с запятой не нужна. Лишняя ; сразу после if создаёт пустую инструкцию.',lang('language-reference/statements/'),[";"],['инструкция','точка с запятой','блок','фигурные скобки']),
 e('comments','Комментарии // и /* */',basics,'Синтаксис','Комментарий объясняет код человеку и не выполняется. // действует до конца строки, /* */ — между указанными границами.','// пояснение\n/* несколько строк */','// Число единиц на складе\nint stock = 8;','Комментарий должен объяснять намерение или причину, а не скрывать ошибочный код навсегда.',lang('language-reference/tokens/comments'),["//","/*"],['комментарий','пояснение кода']),
 e('namespace','namespace',basics,'Ключевое слово','Группирует типы по именованным областям и помогает различать классы с одинаковыми именами. Объявление относится к типам файла, а не создаёт объект.','namespace Имя;','namespace Training;\npublic class Item { }','Файлы одного проекта могут использовать одно пространство имён. Имя папки и namespace не обязаны совпадать, но согласованность упрощает поиск.',lang('language-reference/keywords/namespace'),['namespace'],['пространство имен','пространство имён']),
 e('using-directive','using — подключение пространства имён',basics,'Ключевое слово','Позволяет обращаться к типам пространства имён без полного имени. Эта форма using не открывает файл и не управляет временем жизни объекта.','using Пространство.Имен;','using System.Collections.Generic;\nList<int> stocks = new List<int>();','Не путайте директиву using с using (...) или using var для освобождения ресурсов. В новых проектах часть пространств подключается неявно.',lang('language-reference/keywords/using-directive'),["using System"],['подключение библиотеки','импорт']),
 e('var','var',basics,'Ключевое слово','Просит компилятор определить тип локальной переменной по начальному выражению. Тип остаётся строгим и не меняется во время работы.','var имя = выражение;','var stock = 8; // int\nvar price = 1200m; // decimal','var требует начального значения. Это не dynamic и не разрешение хранить в одной переменной значения любых типов.',lang('language-reference/statements/declarations'),['var'],['неявный тип','вывод типа']),
 e('const','const',basics,'Ключевое слово','Объявляет константу, значение которой известно при компиляции и не может изменяться после объявления.','const тип Имя = значение;','const decimal DiscountPercent = 10m;\ndecimal total = 2200m * (100m - DiscountPercent) / 100m;','Для значения, вычисленного при создании объекта, обычно подходит readonly, а не const.',lang('language-reference/keywords/const'),['const'],['константа','постоянное значение']),
 e('int','int',basics,'Тип','Знаковое целое число длиной 32 бита. Подходит для количества единиц товара, индексов и счётчиков.','int имя = целоеЧисло;','int stock = 8;\nint requested = 3;\nint left = stock - requested;','Деление int на int выполняется как целочисленное: 5 / 2 равно 2. Для дробного результата используйте decimal или double.',lang('language-reference/builtin-types/integral-numeric-types'),['int'],['целое число','количество','System.Int32']),
 e('long','long',basics,'Тип','Знаковое целое число длиной 64 бита. Используется, если диапазона int недостаточно, например для больших счётчиков или идентификаторов.','long имя = значение;','long population = 8_000_000_000L;','Суффикс L делает числовой литерал long. Преобразование long в int может потерять данные или вызвать исключение в checked.',lang('language-reference/builtin-types/integral-numeric-types'),['long'],['System.Int64','большое целое']),
 e('decimal','decimal',basics,'Тип','Десятичный числовой тип с высокой точностью, подходящий для денежных расчётов. Литералы decimal записывают с суффиксом m.','decimal имя = числоm;','decimal price = 1999.90m;\ndecimal total = price * 2;','decimal не устраняет необходимость явно выбирать правило округления. Не смешивайте decimal и double без осознанного преобразования.',lang('language-reference/builtin-types/floating-point-numeric-types'),['decimal'],['цена','деньги','суффикс m','десятичное число']),
 e('double','double',basics,'Тип','Число с плавающей запятой двойной точности. Удобно для измерений и математических вычислений, но многие десятичные дроби хранятся приближённо.','double имя = число;','double distance = 10.5;\ndouble time = 2.0;\ndouble speed = distance / time;','Для денег в учебном каталоге используйте decimal. Проверять результаты double на точное равенство после вычислений часто неправильно.',lang('language-reference/builtin-types/floating-point-numeric-types'),['double'],['плавающая запятая','вещественное число']),
 e('float','float',basics,'Тип','Число с плавающей запятой одинарной точности. Требует суффикса f у дробного литерала и обычно используется, когда важны размер данных или совместимость API.','float имя = числоf;','float fontSize = 18F;','float хранит меньше значащих цифр, чем double. Для денежных сумм этот тип не подходит.',lang('language-reference/builtin-types/floating-point-numeric-types'),['float'],['System.Single','суффикс f']),
 e('bool','bool',basics,'Тип','Хранит одно из двух логических значений: true или false. Результаты сравнений и проверок удобно сохранять в bool.','bool имя = условие;','int quantity = 0;\nbool isAvailable = quantity > 0; // false','bool не является строкой "true" и не является числом 1. В условии if требуется логическое выражение.',lang('language-reference/builtin-types/bool'),['bool','true','false'],['логический тип','истина','ложь']),
 e('string','string',basics,'Тип','Хранит текст как последовательность символов UTF-16. Строки неизменяемы: методы обработки возвращают новую строку.','string имя = "текст";','string name = " Кроссовки ";\nname = name.Trim();','name.Trim() без присваивания не меняет name. string — ссылочный тип; значение null отличается от пустой строки "".',lang('language-reference/builtin-types/reference-types'),['string'],['строка','текст','System.String']),
 e('char','char',basics,'Тип','Хранит одну кодовую единицу UTF-16. Символьный литерал записывают в одинарных кавычках.','char имя = \'символ\';','char separator = \';\';\nchar first = "Товар"[0];','Один видимый символ, например некоторые эмодзи, может состоять из нескольких char. Строка "A" и символ \'A\' имеют разные типы.',lang('language-reference/builtin-types/char'),['char'],['символ','одинарные кавычки']),
 e('nullable','Nullable: int? и string?',basics,'Тип','Позволяет выразить отсутствие значения. int? — Nullable<int>, а string? — аннотация nullable-ссылки для анализа компилятором.','тип? имя = null;','int? selectedId = null;\nint id = selectedId ?? 0;','Перед чтением Value у nullable-числа проверьте HasValue либо используйте ?? или GetValueOrDefault(). Аннотация string? сама не добавляет проверку во время выполнения.',lang('language-reference/builtin-types/nullable-value-types'),[],['nullable','null','необязательное значение']),
 e('object','object',basics,'Тип','Общий базовый тип типов .NET. Через object можно хранить ссылку на разные объекты, но для работы с их специальными свойствами потребуется проверка типа.','object имя = значение;','object value = "Кроссовки";\nif (value is string name)\n    Console.WriteLine(name.Length);','У переменной типа object нет свойства Price только потому, что внутри лежит товар. Пример с Tag в WinForms использует именно проверку типа.',lang('language-reference/builtin-types/reference-types'),['object'],['System.Object','базовый тип']),
 e('void','void',basics,'Ключевое слово','Указывает, что метод не возвращает значение. Метод всё равно может менять состояние объектов, показывать сообщения и завершаться через return;.','void ИмяМетода() { ... }','void PrintName(string name)\n{\n    Console.WriteLine(name);\n}','В void-методе нельзя написать return 10;. Если вызывающий код должен получить число, укажите соответствующий возвращаемый тип.',lang('language-reference/builtin-types/void'),['void'],['метод без результата']),
 e('assignment','= — присваивание',basics,'Оператор','Вычисляет выражение справа и записывает полученное значение в переменную или доступное свойство слева.','леваяЧасть = выражение;','int stock = 8;\nstock = 3;','= изменяет значение. == сравнивает два значения и возвращает bool; эти операторы не взаимозаменяемы.',lang('language-reference/operators/assignment-operator'),['='],['присваивание','записать значение']),
 e('compound','+= и -=',basics,'Оператор','Сочетают арифметическую операцию с присваиванием. Применяются для накопителей, счётчиков и изменения остатка.','имя += значение;\nимя -= значение;','int stock = 8;\nstock -= 2; // 6\nstock += 4; // 10','Не уменьшайте остаток до проверки количества: отказ должен оставлять исходное состояние объекта.',lang('language-reference/operators/assignment-operator'),['+=','-='],['составное присваивание','накопитель']),
 e('arithmetic','+ − * / — арифметика',basics,'Оператор','Выполняют сложение, вычитание, умножение и деление. Типы операндов влияют на результат и точность.','a + b; a - b; a * b; a / b;','decimal price = 1000m;\nint quantity = 2;\ndecimal subtotal = price * quantity;','Умножение и деление выполняются раньше сложения и вычитания. Скобки явно задают нужный порядок.',lang('language-reference/operators/arithmetic-operators'),[" * "," - ","/ 100m"],['арифметика','умножение','деление','сложение','вычитание']),
 e('remainder','% — остаток от деления',basics,'Оператор','Возвращает остаток от деления. Часто нужен для проверки чётности или циклического выбора.','a % b','int rest = 17 % 5; // 2\nbool even = 8 % 2 == 0;','% не вычисляет процент скидки. Процент от суммы находят через subtotal * percent / 100m.',lang('language-reference/operators/arithmetic-operators'),['%'],['остаток от деления','четность','чётность']),
 e('increment','++ и --',basics,'Оператор','Увеличивают или уменьшают значение на единицу. Постфиксная форма возвращает старое значение выражения, префиксная — новое.','i++; ++i; i--; --i;','int count = 0;\ncount++; // count теперь 1','В обычном шаге цикла i++ и ++i дают одно изменение счётчика. Не смешивайте несколько изменений одной переменной в сложном выражении.',lang('language-reference/operators/arithmetic-operators'),['++','--'],['инкремент','декремент','счётчик']),
 e('equality','== и !=',basics,'Оператор','Сравнивают значения на равенство или неравенство и возвращают bool. Для ссылочных типов поведение зависит от типа и его реализации сравнения.','a == b; a != b;','int stock = 3;\nint requested = 3;\nbool lastUnits = requested == stock;','Для строк можно явно указать правила сравнения через string.Equals и StringComparison. == не присваивает новое значение.',lang('language-reference/operators/equality-operators'),['==','!='],['равно','не равно','сравнение']),
 e('relational','< > <= >=',basics,'Оператор','Сравнивают порядок чисел: меньше, больше, не больше и не меньше. Результат имеет тип bool.','a < b; a > b; a <= b; a >= b;','int stock = 3;\nbool low = stock <= 3; // true','В stock <= 3 выполняется сравнение, а не присваивание. Для интервала от 0 до 3 используйте stock >= 0 && stock <= 3.',lang('language-reference/operators/comparison-operators'),['<=','>='],['меньше','больше','граница диапазона']),
 e('and','&& — логическое И',basics,'Оператор','Возвращает true, когда обе части истинны. Правая часть вычисляется только при истинной левой части.','условие1 && условие2','int stock = 3;\nbool low = stock >= 0 && stock <= 3;','Короткое замыкание позволяет поставить безопасную проверку раньше опасного обращения: item != null && item.Stock > 0.',lang('language-reference/operators/boolean-logical-operators'),['&&'],['логическое и','обе проверки']),
 e('or','|| — логическое ИЛИ',basics,'Оператор','Возвращает true, если истинна хотя бы одна часть. Правая часть не вычисляется, если левая уже истинна.','условие1 || условие2','bool invalid = price <= 0m || stock < 0;','Для отклонения ввода достаточно одной ошибки, поэтому проверки часто соединяют через ||. Не путайте его с &&, требующим истинности обеих частей.',lang('language-reference/operators/boolean-logical-operators'),['||'],['логическое или','хотя бы одно']),
 e('not','! — логическое НЕ',basics,'Оператор','Инвертирует bool: true становится false, false становится true.','!условие','bool parsed = int.TryParse("abc", out int stock);\nif (!parsed)\n    Console.WriteLine("Ошибка ввода");','! перед TryParse означает отказ преобразования. Запись is not в шаблоне проверки типа имеет отдельный синтаксис.',lang('language-reference/operators/boolean-logical-operators'),['!'],['отрицание','неверно']),
 e('conditional','?: — условное выражение',basics,'Оператор','Выбирает одно из двух значений в зависимости от bool-условия. Подходит для короткого выбора результата.','условие ? значениеЕслиTrue : значениеЕслиFalse','int stock = 0;\nstring status = stock > 0 ? "Есть" : "Нет";','Для нескольких проверок и действий if обычно понятнее. Не вкладывайте много условных операторов друг в друга.',lang('language-reference/operators/conditional-operator'),[],['тернарный оператор','условный оператор']),
 e('null-conditional','?. — условный доступ',basics,'Оператор','Обращается к члену объекта только если ссылка не null. При null результат обращения тоже отсутствует.','ссылка?.Член','string? name = null;\nint length = name?.Length ?? 0;','?. не исправляет неверный индекс и не скрывает исключения самого метода. В таблице CurrentRow?.Tag защищает только отсутствие CurrentRow.',lang('language-reference/operators/member-access-operators'),['?.'],['безопасный доступ','null conditional']),
 e('coalescing','?? — значение вместо null',basics,'Оператор','Возвращает левое значение, если оно не null; иначе вычисляет и возвращает правое.','возможноNull ?? запасноеЗначение','string? name = null;\nstring shown = name ?? "Без названия";','Пустая строка и ноль не являются null. Для пустого текста нужна отдельная проверка IsNullOrWhiteSpace.',lang('language-reference/operators/null-coalescing-operator'),['??'],['объединение с null','значение по умолчанию']),
 e('cast','(тип) — явное преобразование',basics,'Оператор','Явно указывает переход к другому совместимому типу. Для чисел преобразование может отбросить дробную часть или выйти за диапазон.','(тип)выражение','decimal value = 2.9m;\nint quantity = (int)value; // 2','Приведение к int не округляет до ближайшего целого. Для строки "12" используйте TryParse, а не (int).',lang('programming-guide/types/casting-and-type-conversions'),["(int)","(decimal)"],['приведение типа','каст','преобразование']),
 e('nameof','nameof',basics,'Оператор','Получает имя переменной, типа или члена как строку во время компиляции. Помогает избежать несогласованных строк при переименовании.','nameof(идентификатор)','string label = nameof(String.Length); // "Length"','nameof возвращает имя, а не значение переменной и не полное имя типа.',lang('language-reference/operators/nameof'),['nameof'],['имя параметра','переименование']),
 e('typeof','typeof',basics,'Оператор','Получает объект Type, описывающий тип. Используется в обобщённых механизмах, диагностике и рефлексии.','typeof(Тип)','Type numberType = typeof(int);\nstring name = numberType.Name; // Int32','typeof требует имя типа. Для определения типа уже созданного объекта обычно используют GetType(), предварительно учитывая null.',lang('language-reference/operators/type-testing-and-cast'),['typeof'],['тип объекта','System.Type']),
 e('if','if',basics,'Ключевое слово','Выполняет блок, если условие имеет значение true. Проверки до изменения данных помогают отклонять неверный ввод.','if (условие) { инструкции; }','if (requested > stock)\n{\n    Console.WriteLine("Недостаточно товара");\n    return;\n}','Точка с запятой сразу после if создаёт пустое тело. Условие должно возвращать bool.',lang('language-reference/statements/selection-statements'),['if'],['условие','проверка']),
 e('else-if','else if и else',basics,'Ключевое слово','Цепочка выбирает первый подходящий блок. else if проверяется после ложных предыдущих условий, а else используется, если ни одна проверка не подошла.','if (...) { ... } else if (...) { ... } else { ... }','if (stock == 0)\n    status = "Нет";\nelse if (stock <= 3)\n    status = "Мало";\nelse\n    status = "Достаточно";','Порядок важен: проверка stock <= 3 до stock == 0 захватит и нулевой остаток.',lang('language-reference/statements/selection-statements'),['else'],['иначе','ветвление','цепочка условий']),
 e('switch','switch, case, default',basics,'Ключевое слово','Выбирает ветку по значению или шаблону. В простом выборе категорий case соответствует варианту, default — всем оставшимся случаям.','switch (значение) { case вариант: ... break; default: ... break; }','switch (category)\n{\n    case "Сандалии": status = "Летняя обувь"; break;\n    default: status = "Другая категория"; break;\n}','break выходит из switch, а не из всего обработчика. Строки вариантов должны соответствовать данным списка.',lang('language-reference/statements/selection-statements'),['switch','case','default'],['выбор категории','несколько вариантов']),
 e('for','for',basics,'Цикл','Повторяет тело с начальной настройкой, условием продолжения и шагом. Подходит для доступа к элементам по индексу.','for (начало; условие; шаг) { ... }','int[] stocks = { 2, 8, 0 };\nint total = 0;\nfor (int i = 0; i < stocks.Length; i++)\n    total += stocks[i];','Последний индекс массива равен Length - 1. Условие i <= stocks.Length приведёт к выходу за границы.',lang('language-reference/statements/iteration-statements'),['for'],['цикл со счётчиком','индекс']),
 e('while','while',basics,'Цикл','Повторяет тело, пока условие истинно. Если условие сразу ложно, тело не выполняется ни разу.','while (условие) { ... }','int count = 0;\nwhile (count < 3)\n    count++;','В теле должно происходить изменение, которое может сделать условие ложным; иначе цикл способен зависнуть.',lang('language-reference/statements/iteration-statements'),['while'],['цикл с условием','бесконечный цикл']),
 e('do-while','do ... while',basics,'Цикл','Проверяет условие после тела, поэтому выполняет тело минимум один раз.','do { ... } while (условие);','int attempts = 0;\ndo\n{\n    attempts++;\n} while (attempts < 3);','После while в этой конструкции нужна точка с запятой. В интерфейсе WinForms не блокируйте UI длинным циклом ожидания.',lang('language-reference/statements/iteration-statements'),['do'],['цикл с постусловием']),
 e('foreach','foreach',basics,'Цикл','Последовательно получает элементы коллекции без ручного управления индексом. Переменная цикла представляет текущий элемент.','foreach (Тип item in коллекция) { ... }','List<int> stocks = new List<int> { 2, 8, 0 };\nint total = 0;\nforeach (int stock in stocks)\n    total += stock;','Обычно нельзя добавлять или удалять элементы того же List во время его перебора foreach. Свойства самих объектов можно изменять, если это допускает их модель.',lang('language-reference/statements/iteration-statements'),['foreach'],['перебор','обход коллекции']),
 e('break','break',basics,'Ключевое слово','Завершает ближайший цикл или switch и передаёт выполнение инструкции после него.','break;','foreach (int stock in stocks)\n{\n    if (stock == 0) break;\n}','break не завершает метод. Для завершения обработчика используют return.',lang('language-reference/statements/jump-statements'),['break'],['выход из цикла']),
 e('continue','continue',basics,'Ключевое слово','Пропускает оставшиеся инструкции текущей итерации и переходит к следующей итерации ближайшего цикла.','continue;','foreach (int stock in stocks)\n{\n    if (stock == 0) continue;\n    total += stock;\n}','В while нужно следить, чтобы continue не обходил изменение счётчика или другой шаг завершения.',lang('language-reference/statements/jump-statements'),['continue'],['пропустить итерацию']),
 e('return','return',basics,'Ключевое слово','Завершает текущий метод. В void-методе пишут return;, а в методе с результатом возвращают подходящее значение.','return;\nreturn выражение;','decimal CalculateTotal(decimal price, int quantity)\n{\n    return price * quantity;\n}','return завершает вызов метода, а не обязательно всё приложение. При вызове из другого метода управление вернётся вызывающему коду.',lang('language-reference/statements/jump-statements'),['return'],['вернуть результат','ранний выход']),
 e('out','out',basics,'Ключевое слово','Позволяет методу записать результат в переданный аргумент. Метод обязан присвоить out-параметру значение перед нормальным завершением.','Метод(..., out Тип имя)','bool ok = int.TryParse("12", out int stock);\nif (ok) Console.WriteLine(stock);','При false у TryParse нельзя принимать получившийся 0 как корректно введённый остаток: проверяйте bool результата.',lang('language-reference/keywords/method-parameters'),['out'],['выходной параметр','результат преобразования']),
 e('ref','ref',basics,'Ключевое слово','Передаёт переменную по ссылке, позволяя методу читать и изменять её значение. Переменная должна быть присвоена до вызова.','Метод(ref переменная)','void Increment(ref int number) { number++; }\nint count = 2;\nIncrement(ref count); // 3','ref нужен и в объявлении параметра, и в вызове. Не используйте ref там, где достаточно обычного возвращаемого значения.',lang('language-reference/keywords/method-parameters'),['ref'],['передача по ссылке']),
 e('params','params',basics,'Ключевое слово','Разрешает передавать методу переменное число аргументов. Классическая совместимая форма использует массив последним параметром.','void Метод(params Тип[] значения)','int Total(params int[] values)\n{\n    return values.Sum();\n}\nint sum = Total(2, 3, 4);','Для Sum требуется System.Linq. params-параметр один и в классической форме должен быть последним.',lang('language-reference/keywords/method-parameters'),['params'],['переменное число аргументов']),
 e('lambda','=> — лямбда-выражение',basics,'Синтаксис','Описывает короткую функцию, которую можно передать другому методу. Часто применяется для условий фильтрации и преобразования в LINQ.','параметр => выражение','int[] stocks = { 2, 8, 0 };\nvar low = stocks.Where(stock => stock <= 3);','Для LINQ требуется System.Linq. Лямбда задаёт функцию, но отложенный запрос может выполнить её только при перечислении результата.',lang('language-reference/operators/lambda-expressions'),['=>'],['лямбда','анонимная функция']),

 e('class','class',oop,'Ключевое слово','Объявляет ссылочный тип: описание данных и поведения будущих объектов. Само объявление класса ещё не создаёт экземпляр.','class Имя { члены }','public class Box\n{\n    public int Count { get; set; }\n}','Определение класса размещают на уровне пространства имён либо внутри другого типа, а не внутри обработчика кнопки.',lang('fundamentals/types/classes'),['class'],['класс','описание объекта']),
 e('instance','Экземпляр и ссылка на объект',oop,'Понятие','Экземпляр — конкретный созданный объект класса. Переменная ссылочного типа хранит ссылку на объект; копирование ссылки не создаёт копию самого объекта.','Тип a = new Тип(); Тип b = a;','var first = new List<int> { 2 };\nvar second = first;\nsecond.Add(8); // first тоже содержит 2 и 8','Чтобы получить независимые данные, нужна осознанная копия. new List<T>(items) копирует список, но не обязательно объекты внутри него.',lang('fundamentals/types/classes'),['new'],['объект','экземпляр','ссылка']),
 e('new','new',oop,'Ключевое слово','Создаёт экземпляр типа и вызывает его конструктор. Для классов результатом является ссылка на новый объект.','new Тип(аргументы)','List<string> names = new List<string>();\nnames.Add("Кроссовки");','Создание новой карточки формы не должно создавать случайный новый товар вместо передачи уже выбранного объекта.',lang('language-reference/operators/new-operator'),['new'],['создание объекта']),
 e('constructor','Конструктор класса',oop,'Понятие','Специальный член с именем класса, который подготавливает новый экземпляр. У конструктора нет возвращаемого типа, даже void.','public ИмяКласса(параметры) { ... }','public class Box\n{\n    public int Count { get; }\n    public Box(int count) { Count = count; }\n}','Порядок аргументов в new должен соответствовать параметрам конструктора. Проверка исходных данных в конструкторе защищает все места создания объектов.',lang('programming-guide/classes-and-structs/constructors'),["new Product(","public Product(","new ProductDetailsForm(","public ProductDetailsForm(","new CatalogForm(","public CatalogForm("],['конструктор','параметры конструктора']),
 e('property','Свойство: get и set',oop,'Синтаксис','Предоставляет управляемое чтение и запись значения. Автосвойство создаёт скрытое хранилище, если отдельное поле не требуется.','public Тип Имя { get; set; }','public class Box\n{\n    public int Count { get; set; }\n}','Свойство — не вызов метода: пишут item.Price, а не item.Price(). set можно ограничить или заменить проверками.',lang('programming-guide/classes-and-structs/properties'),['get','set'],['свойство','автосвойство']),
 e('private-set','get; private set;',oop,'Синтаксис','Разрешает внешнему коду читать свойство, но разрешает присваивание только из содержащего класса. Это помогает менять состояние через проверяющие методы.','public Тип Имя { get; private set; }','public class StockCounter\n{\n    public int Count { get; private set; }\n    public void AddOne() { Count++; }\n}','private set само по себе не проверяет диапазон. Логика методов класса всё равно должна отклонять неверные значения.',lang('programming-guide/classes-and-structs/restricting-accessor-accessibility'),['private set'],['инкапсуляция','закрытая запись']),
 e('public','public',oop,'Модификатор доступа','Делает тип или член доступным коду, который имеет доступ к содержащему типу. Используется для открытого интерфейса объекта.','public Тип Имя { ... }','public class Box\n{\n    public int Count { get; private set; }\n}','Открывайте только то, что действительно необходимо пользователям класса. Публичная возможность менять остаток без проверок обходит правила объекта.',lang('language-reference/keywords/public'),['public'],['открытый доступ']),
 e('private','private',oop,'Модификатор доступа','Ограничивает доступ к члену содержащим типом. Внутренние поля и вспомогательные методы обычно скрывают от внешнего кода.','private Тип имя;','public class Box\n{\n    private int _count;\n    public int ReadCount() => _count;\n}','Другая форма не может напрямую обращаться к private-полю каталога. Передавайте нужные объекты явно через параметры.',lang('language-reference/keywords/private'),['private'],['закрытый доступ','скрыть поле']),
 e('protected','protected',oop,'Модификатор доступа','Разрешает доступ внутри класса и его производных типов. Применяется, когда наследнику нужна контролируемая точка расширения.','protected Тип Имя;','public class BaseItem\n{\n    protected int _stock;\n}','protected не делает член доступным всему проекту. Для простого учебного класса чаще достаточно public-методов и private-данных.',lang('language-reference/keywords/protected'),['protected'],['доступ наследнику']),
 e('static','static',oop,'Модификатор','Указывает, что член относится к самому типу, а не к отдельному экземпляру. Вызов обычно выполняется через имя типа.','Тип.СтатическийМетод(...)','int stock = int.Parse("12");\ndecimal rounded = decimal.Round(12.345m, 2);','Не делайте Stock статическим: тогда все товары будут делить одно общее значение остатка.',lang('language-reference/keywords/static'),['static'],['статический метод','общий член']),
 e('readonly','readonly',oop,'Модификатор','Ограничивает присваивание поля объявлением и конструктором соответствующего класса. Для ссылочного поля защищает ссылку, а не изменяемость объекта.','private readonly Тип _имя;','public class Catalog\n{\n    private readonly List<string> _names = new();\n    public void Add(string name) => _names.Add(name);\n}','readonly List<T> всё ещё допускает Add и Remove. Запрещается заменить само поле другим списком после инициализации.',lang('language-reference/keywords/readonly'),['readonly'],['поле только для чтения']),
 e('interface','interface',oop,'Ключевое слово','Описывает контракт, который реализующие типы обязуются поддерживать. Позволяет работать с разными классами через общие возможности.','interface Имя { члены }','public interface IHasName\n{\n    string Name { get; }\n}','Интерфейс задаёт доступные операции, но new IHasName() сам по себе невозможен: нужен реализующий тип.',lang('fundamentals/types/interfaces'),['interface'],['интерфейс','контракт']),
 e('inheritance','Наследование :',oop,'Понятие','Позволяет объявить класс на основе другого класса и дополнить его поведение. Класс C# имеет не более одного непосредственного базового класса.','class Наследник : БазовыйКласс','public class Item { }\npublic class SportItem : Item { }','Не путайте отношение «является разновидностью» с «содержит»: каталог содержит товары, но не является товаром.',lang('fundamentals/object-oriented/inheritance'),[],['наследование','базовый класс','производный класс']),
 e('override','virtual и override',oop,'Модификатор','virtual разрешает переопределение метода в наследнике, override предоставляет новую реализацию. Выбор реализации зависит от фактического типа объекта.','public virtual Тип Метод();\npublic override Тип Метод();','public class Item { public virtual string GetName() => "Товар"; }\npublic class Ball : Item { public override string GetName() => "Мяч"; }','new для скрытия метода и override для переопределения — разные механизмы. Базовый метод должен разрешать переопределение.',lang('language-reference/keywords/override'),['override','virtual'],['полиморфизм','переопределение']),
 e('enum','enum',oop,'Тип','Объявляет именованный набор констант на основе целого типа. Помогает заменить неясные числа понятными вариантами.','enum Имя { Вариант1, Вариант2 }','enum StockState { Empty, Low, Available }\nclass Item\n{\n    public StockState State { get; set; } = StockState.Low;\n}','enum не проверяет автоматически, что число входит в объявленный набор: явное приведение может создать и другое значение.',lang('language-reference/builtin-types/enum'),['enum'],['перечисление','набор вариантов']),
 e('parameter','Параметр и аргумент',oop,'Понятие','Параметр — именованное входное значение в объявлении метода; аргумент — конкретное значение, переданное при вызове.','Тип Метод(Тип параметр)','decimal ApplyDiscount(decimal price, decimal percent)\n{\n    return price * (100m - percent) / 100m;\n}\n// Вызов: ApplyDiscount(2200m, 10m)','Одинаковый тип нескольких параметров не защищает от перепутанного порядка. Давайте параметрам ясные имена и сверяйте вызов с объявлением.',lang('programming-guide/classes-and-structs/methods'),["параметр","аргумент"],['параметр','аргумент','метод','вызов метода']),

 e('trim','String.Trim()',strings,'Метод','Возвращает новую строку без пробельных символов по краям. Пробелы внутри названия сохраняются.','строка.Trim()','string name = "  Спортивный мяч  ".Trim();\n// "Спортивный мяч"','Сохраните возвращённую строку. Метод нельзя вызывать у null без предварительной проверки или условного доступа.',api('system.string.trim'),['Trim'],['убрать пробелы','обрезать края']),
 e('trim-start','String.TrimStart()',strings,'Метод','Удаляет пробельные символы только с начала строки и возвращает результат. Конец строки остаётся прежним.','строка.TrimStart()','string name = "  Мяч  ".TrimStart();\n// "Мяч  "','Если нужно очистить оба края пользовательского ввода, используйте Trim().',api('system.string.trimstart'),['TrimStart'],['пробелы слева']),
 e('trim-end','String.TrimEnd()',strings,'Метод','Удаляет пробельные символы только с конца строки. Полезен для обработки строк текстового файла.','строка.TrimEnd()','string line = "Мяч   ".TrimEnd(); // "Мяч"','TrimEnd не меняет исходный экземпляр строки; используйте возвращённое значение.',api('system.string.trimend'),['TrimEnd'],['пробелы справа']),
 e('null-empty','String.IsNullOrEmpty()',strings,'Метод','Возвращает true для null и пустой строки. Строка из одних пробелов считается непустой.','string.IsNullOrEmpty(текст)','bool a = string.IsNullOrEmpty(""); // true\nbool b = string.IsNullOrEmpty("   "); // false','Для проверки обязательного поля интерфейса чаще подходит IsNullOrWhiteSpace.',api('system.string.isnullorempty'),['IsNullOrEmpty'],['пустая строка']),
 e('null-whitespace','String.IsNullOrWhiteSpace()',strings,'Метод','Проверяет null, пустую строку и строку, состоящую только из пробельных символов. Удобен для обязательных полей.','string.IsNullOrWhiteSpace(текст)','string name = "   ";\nif (string.IsNullOrWhiteSpace(name))\n    Console.WriteLine("Укажите название");','Проверка возвращает bool и не очищает значение. Для дальнейшего хранения имени обычно дополнительно применяют Trim().',api('system.string.isnullorwhitespace'),['IsNullOrWhiteSpace'],['проверка пустого ввода','валидация названия']),
 e('string-length','String.Length',strings,'Свойство','Возвращает число кодовых единиц UTF-16 в строке. У обычного русского слова это обычно соответствует числу букв.','строка.Length','string article = "AB12";\nbool longEnough = article.Length >= 4;','Length — свойство, поэтому скобки не нужны. Для null обращение вызовет исключение.',api('system.string.length'),["article.Length","name.Length"],['длина строки','число символов']),
 e('string-contains','String.Contains()',strings,'Метод','Проверяет, есть ли внутри строки указанная подстрока или символ. Возвращает bool.','строка.Contains(фрагмент)','bool hasSpace = "AB 12".Contains(" ");\nbool found = "Кроссовки".Contains("кросс", StringComparison.OrdinalIgnoreCase);','Перегрузку с StringComparison используйте в современной .NET, чтобы явно задать правила сравнения. Contains не возвращает индекс.',api('system.string.contains'),['Contains'],['найти подстроку','содержит']),
 e('starts-with','String.StartsWith()',strings,'Метод','Проверяет начало строки. Полезен для поиска по префиксу и проверки условного формата артикула.','строка.StartsWith(префикс, правила)','bool ok = "AB123".StartsWith("AB", StringComparison.Ordinal);','Для технических кодов задавайте Ordinal или OrdinalIgnoreCase. Одной проверки префикса может быть недостаточно для полной валидации.',api('system.string.startswith'),['StartsWith'],['начинается с','префикс']),
 e('ends-with','String.EndsWith()',strings,'Метод','Проверяет, заканчивается ли строка заданным фрагментом. Возвращает bool.','строка.EndsWith(суффикс, правила)','bool textFile = "report.txt".EndsWith(".txt", StringComparison.OrdinalIgnoreCase);','Для анализа пути к файлу удобнее Path.GetExtension: текстовый суффикс не проверяет существование файла.',api('system.string.endswith'),['EndsWith'],['заканчивается на','суффикс']),
 e('index-of','String.IndexOf()',strings,'Метод','Возвращает индекс первого найденного вхождения либо -1, если фрагмент не найден. Индексы начинаются с нуля.','строка.IndexOf(фрагмент, правила)','int index = "AB-123".IndexOf("-", StringComparison.Ordinal); // 2','Не используйте результат как индекс без проверки >= 0. IndexOf и Contains отвечают на разные вопросы.',api('system.string.indexof'),['IndexOf'],['позиция подстроки','индекс символа']),
 e('substring','String.Substring()',strings,'Метод','Создаёт строку из указанного диапазона исходной строки. Принимает начальный индекс и при необходимости длину.','строка.Substring(начало, длина)','string code = "AB123".Substring(0, 2); // "AB"','Если начало или длина выходят за границы, будет исключение. Длина не является индексом последнего символа.',api('system.string.substring'),['Substring'],['часть строки','вырезать текст']),
 e('replace','String.Replace()',strings,'Метод','Возвращает строку, в которой все найденные вхождения указанного фрагмента заменены новым текстом.','строка.Replace(старое, новое)','string code = "AB-12-3".Replace("-", ""); // "AB123"','Replace не меняет исходную строку. Замена десятичного разделителя вручную не заменяет осознанный выбор CultureInfo при разборе чисел.',api('system.string.replace'),['Replace'],['заменить текст']),
 e('split','String.Split()',strings,'Метод','Разделяет строку по указанным разделителям и возвращает массив частей. Можно удалить пустые части и обрезать пробелы.','строка.Split(разделитель, опции)','string[] names = "Мяч; Ракетка;;".Split(\';\',\n    StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);','TrimEntries доступен в современной .NET. Split не подходит для полноценного CSV с кавычками и разделителями внутри полей.',api('system.string.split'),['Split'],['разделить строку','массив строк']),
 e('join','String.Join()',strings,'Метод','Соединяет элементы коллекции в одну строку, помещая разделитель между соседними элементами.','string.Join(разделитель, элементы)','string line = string.Join(", ", new[] { "Мяч", "Ракетка" });\n// "Мяч, Ракетка"','Join не добавляет разделитель в конец строки. Для отображения разных строк можно использовать Environment.NewLine.',api('system.string.join'),['Join'],['объединить строки','список через запятую']),
 e('upper-invariant','String.ToUpperInvariant()',strings,'Метод','Возвращает строку в верхнем регистре с использованием правил инвариантной культуры. Удобен для нормализации технических артикулов.','строка.ToUpperInvariant()','string article = " ab12 ".Trim().ToUpperInvariant(); // "AB12"','Для сравнения строк без учёта регистра предпочтительно явно указать OrdinalIgnoreCase, а не создавать две новые строки.',api('system.string.toupperinvariant'),['ToUpperInvariant'],['верхний регистр','нормализация артикула']),
 e('lower-invariant','String.ToLowerInvariant()',strings,'Метод','Возвращает строку в нижнем регистре по инвариантным правилам. Исходная строка не изменяется.','строка.ToLowerInvariant()','string code = "ABC".ToLowerInvariant(); // "abc"','Не используйте преобразование регистра как универсальное правило сортировки имён людей: языковые правила могут отличаться.',api('system.string.tolowerinvariant'),['ToLowerInvariant'],['нижний регистр']),
 e('string-equals','String.Equals()',strings,'Метод','Сравнивает две строки и возвращает bool. Статическая перегрузка позволяет безопасно сравнить и null-значения с явными правилами.','string.Equals(a, b, StringComparison.правило)','bool same = string.Equals("SportLine", "sportline",\n    StringComparison.OrdinalIgnoreCase); // true','В проверке дубликата товара обычно должны совпасть и название, и производитель. Одного совпавшего поля недостаточно.',api('system.string.equals'),['Equals'],['сравнение строк','дубликат']),
 e('string-comparison','StringComparison.OrdinalIgnoreCase',strings,'Перечисление','Задаёт порядковое сравнение строк без учёта регистра, не зависящее от текущего языка пользователя. Подходит для технических имён и кодов.','StringComparison.OrdinalIgnoreCase','bool same = string.Equals("AB12", "ab12",\n    StringComparison.OrdinalIgnoreCase);','Для лингвистической сортировки отображаемых имён могут требоваться правила конкретной культуры. OrdinalIgnoreCase не удаляет пробелы.',api('system.stringcomparison'),['StringComparison','OrdinalIgnoreCase'],['без учета регистра','без учёта регистра']),
 e('interpolation','$"...{value}..."',strings,'Синтаксис','Вставляет значения выражений в текст строки. Внутри фигурных скобок можно указать формат вывода.','$"Текст {выражение:формат}"','decimal price = 2200m;\nint stock = 2;\nstring info = $"Цена: {price:N2} ₽; остаток: {stock}";','Буква $ должна стоять перед открывающей кавычкой. Для вывода самой фигурной скобки используйте {{ или }}.',lang('language-reference/tokens/interpolated'),["$\""],['интерполяция','подстановка','строка с долларом']),
 e('format-n2','N2 — формат числа',strings,'Формат','Выводит число с разделением групп разрядов и двумя цифрами после десятичного разделителя. Вид разделителей зависит от культуры.','значение.ToString("N2")\n$"{значение:N2}"','decimal price = 2200m;\nstring label = $"{price:N2} ₽";','Форматирование меняет текст, а не числовое значение price. Для математического округления используйте decimal.Round с явным правилом.', 'https://learn.microsoft.com/en-us/dotnet/standard/base-types/standard-numeric-format-strings',['N2'],['два знака после запятой','формат денег']),
 e('new-line','Environment.NewLine',strings,'Свойство','Возвращает перевод строки для текущей платформы. Помогает строить многострочный текст без жёстко заданных управляющих символов.','Environment.NewLine','string info = "Товар: Мяч" + Environment.NewLine + "Остаток: 2";','Чтобы видеть несколько строк в WinForms, элемент должен иметь подходящие размер и настройки. Для переноса строки не добавляйте отдельную метку на каждую строку.',api('system.environment.newline'),['NewLine'],['перевод строки','новая строка']),

 e('int-tryparse','Int32.TryParse()',nums,'Метод','Пробует преобразовать текст в целое число. Возвращает признак успеха и записывает число в out-параметр.','int.TryParse(текст, out int число)','if (!int.TryParse("12", out int stock))\n    Console.WriteLine("Введите целое число");','Успешный разбор не проверяет ваши бизнес-правила: после него отдельно отклоните отрицательный остаток или слишком большое значение.',api('system.int32.tryparse'),['int.TryParse'],['int.TryParse','целое из текста','проверка числа']),
 e('int-parse','Int32.Parse()',nums,'Метод','Преобразует текст в int, но при неверном формате или выходе за диапазон выбрасывает исключение.','int.Parse(текст)','int stock = int.Parse("12");','Для непроверенного пользовательского ввода обычно удобнее TryParse. Parse не следует применять к любому TextBox без обработки ошибки.',api('system.int32.parse'),['int.Parse'],['int.Parse','преобразовать в int']),
 e('decimal-tryparse','Decimal.TryParse()',nums,'Метод','Пробует прочитать decimal из текста. Результат зависит от правил формата числа и выбранной культуры.','decimal.TryParse(текст, out decimal число)','bool ok = decimal.TryParse("1234.50",\n    System.Globalization.NumberStyles.Number,\n    System.Globalization.CultureInfo.InvariantCulture, out decimal price);','Обычная перегрузка использует текущую культуру: для ru-RU ожидаемым разделителем обычно будет запятая. Проверку price > 0 выполняйте отдельно.',api('system.decimal.tryparse'),['decimal.TryParse'],['decimal.TryParse','цена из текста','десятичный разделитель']),
 e('decimal-parse','Decimal.Parse()',nums,'Метод','Преобразует текст в decimal по правилам культуры или заданному провайдеру. При ошибке выбрасывает исключение.','decimal.Parse(текст, культура)','decimal price = decimal.Parse("2200.50",\n    System.Globalization.CultureInfo.InvariantCulture);','Для полей ввода используйте TryParse, если неверный текст является обычной ожидаемой ситуацией.',api('system.decimal.parse'),['decimal.Parse'],['decimal.Parse','разбор цены']),
 e('decimal-round','Decimal.Round()',nums,'Метод','Округляет decimal до указанного количества десятичных знаков. Перегрузка позволяет явно выбрать обработку середины.','decimal.Round(число, знаков, правило)','decimal total = decimal.Round(12.345m, 2,\n    MidpointRounding.AwayFromZero); // 12.35','Без явного правила применяется округление середины к ближайшему чётному. Не путайте округление с форматированием N2.',api('system.decimal.round'),["decimal.Round"],['decimal.Round','округление денег']),
 e('midpoint','MidpointRounding',nums,'Перечисление','Определяет, как обрабатывать значения при округлении. AwayFromZero для точной середины выбирает направление от нуля; ToEven — ближайшую чётную последнюю цифру.','MidpointRounding.ToEven\nMidpointRounding.AwayFromZero','decimal a = decimal.Round(2.5m, 0, MidpointRounding.ToEven); // 2\ndecimal b = decimal.Round(2.5m, 0, MidpointRounding.AwayFromZero); // 3','Правило округления должно соответствовать задаче. Название AwayFromZero не означает, что любое значение всегда округляется в большую сторону.',api('system.midpointrounding'),['MidpointRounding','AwayFromZero'],['банковское округление','округление середины']),
 e('math-min','Math.Min()',nums,'Метод','Возвращает меньшее из двух чисел. Полезен для выбора верхнего ограничения результата.','Math.Min(a, b)','int requested = 10;\nint stock = 3;\nint limited = Math.Min(requested, stock); // 3','В заказе нельзя молча заменять недопустимый запрос ограниченным количеством, если задание требует отказа. Min — вычисление, а не проверка согласия пользователя.',api('system.math.min'),["Math.Min"],['минимум']),
 e('math-max','Math.Max()',nums,'Метод','Возвращает большее из двух чисел. Может использоваться для нижнего ограничения вычисляемого значения.','Math.Max(a, b)','int calculated = -2;\nint visible = Math.Max(0, calculated); // 0','Не маскируйте ошибку состояния: отрицательный складской остаток обычно надо предотвратить проверкой, а не только скрыть при выводе.',api('system.math.max'),["Math.Max"],['максимум']),
 e('math-clamp','Math.Clamp()',nums,'Метод','Ограничивает значение диапазоном: ниже минимума возвращает минимум, выше максимума — максимум, внутри сохраняет значение.','Math.Clamp(value, min, max)','int percent = Math.Clamp(120, 0, 100); // 100','Если min > max, метод выбрасывает исключение. Ограничение значения и сообщение об ошибочном вводе — разные решения интерфейса.',api('system.math.clamp'),["Math.Clamp"],['ограничить диапазон']),
 e('math-abs','Math.Abs()',nums,'Метод','Возвращает абсолютное значение числа, то есть расстояние от нуля без знака.','Math.Abs(число)','int difference = 3 - 8;\nint distance = Math.Abs(difference); // 5','Не превращайте отрицательный ввод остатка в положительный без основания: чаще требуется отказ. Минимальное значение знакового целого имеет особый случай переполнения.',api('system.math.abs'),["Math.Abs"],['модуль числа']),
 e('datetime-now','DateTime.Now и DateTime.UtcNow',nums,'Свойство','Now получает текущие локальные дату и время, UtcNow — текущее время UTC. Это значения времени на момент обращения.','DateTime.Now\nDateTime.UtcNow','DateTime local = DateTime.Now;\nDateTime utc = DateTime.UtcNow;','Не смешивайте локальное время и UTC без преобразования. Для хранения момента с явным смещением часто удобнее DateTimeOffset.',api('system.datetime.now'),['DateTime','UtcNow'],['текущее время','сегодня сейчас','UTC']),
 e('datetime-today','DateTime.Today',nums,'Свойство','Возвращает текущую локальную дату с временем 00:00:00. Подходит для сравнения дат, когда время суток не нужно.','DateTime.Today','DateTime reportDate = DateTime.Today;','Today относится к локальной дате компьютера. Для чисто календарной даты в современной .NET также существует DateOnly.',api('system.datetime.today'),['Today'],['сегодняшняя дата']),
 e('add-days','DateTime.AddDays()',nums,'Метод','Возвращает новую дату и время со сдвигом на указанное число суток. Исходное значение DateTime не меняется.','дата.AddDays(числоДней)','DateTime deadline = DateTime.Today.AddDays(7);','Это календарный сдвиг, а не расчёт рабочих дней: выходные и праздники метод не исключает.',api('system.datetime.adddays'),['AddDays'],['прибавить дни','срок']),
 e('datetime-tryparse','DateTime.TryParse()',nums,'Метод','Пробует преобразовать текст в дату и время с учётом правил формата. Возвращает bool, а разобранное значение записывает в out-параметр.','DateTime.TryParse(текст, out DateTime дата)','bool ok = DateTime.TryParse("31.10.2026",\n    System.Globalization.CultureInfo.GetCultureInfo("ru-RU"),\n    System.Globalization.DateTimeStyles.None, out DateTime date);','Для строго заданного формата предпочтительнее TryParseExact. В неоднозначной записи вроде 01/02/2026 смысл зависит от культуры.',api('system.datetime.tryparse'),['DateTime.TryParse'],['разбор даты','дата из строки']),
 e('timespan','TimeSpan',nums,'Тип','Представляет интервал времени, а не календарную дату. Получается, например, вычитанием двух DateTime.','TimeSpan.FromMinutes(число)','TimeSpan lesson = TimeSpan.FromMinutes(90);\ndouble hours = lesson.TotalHours; // 1.5','Hours — компонент часов внутри интервала, TotalHours — полное число часов, включая дни и дробную часть.',api('system.timespan'),['TimeSpan'],['длительность','интервал времени']),

 e('array','Массив T[]',collections,'Тип','Хранит последовательность элементов одного типа с фиксированной длиной. Элементы доступны по индексу от 0 до Length - 1.','Тип[] имя = { значения };','int[] stocks = { 2, 8, 0 };\nint first = stocks[0];','Массив не увеличивается при добавлении элементов. Если размер должен меняться, используйте List<T>.',lang('language-reference/builtin-types/arrays'),["int[]","массив"],['массив','индекс','элементы массива']),
 e('array-length','Array.Length',collections,'Свойство','Возвращает общее количество элементов массива. Это количество, а не последний допустимый индекс.','массив.Length','int[] stocks = { 2, 8, 0 };\nint count = stocks.Length; // 3','Обращение stocks[stocks.Length] выходит за границы. Для List<T> используется Count, а не Length.',api('system.array.length'),["stocks.Length"],['длина массива','размер массива']),
 e('list','List<T>',collections,'Тип','Изменяемый список элементов одного типа. T указывает тип элемента, например int, string или собственный класс.','List<Тип> имя = new List<Тип>();','List<int> stocks = new List<int> { 2, 8 };\nstocks.Add(0);','Count показывает число элементов списка. Для списка товаров это число позиций, а не сумма складских остатков.',api('system.collections.generic.list-1'),['List'],['список','коллекция','обобщенный тип','обобщённый тип']),
 e('list-add','List<T>.Add()',collections,'Метод','Добавляет один элемент в конец списка. Список хранит переданный объект, а не автоматически созданную независимую копию.','список.Add(элемент)','List<string> names = new();\nnames.Add("Мяч");','Не вызывайте Add повторно в примере очистки полей после уже успешного добавления: это создаст дубликат позиции.',api('system.collections.generic.list-1.add'),["products.Add","_products.Add"],['добавить элемент']),
 e('list-add-range','List<T>.AddRange()',collections,'Метод','Добавляет в конец списка все элементы переданной последовательности.','список.AddRange(элементы)','List<int> stocks = new() { 2 };\nstocks.AddRange(new[] { 8, 0, 12 });','Повторный AddRange повторно добавит те же значения. Метод не проверяет уникальность и не очищает старый список.',api('system.collections.generic.list-1.addrange'),['AddRange'],['добавить несколько элементов']),
 e('list-count','List<T>.Count',collections,'Свойство','Показывает фактическое число элементов списка. Изменяется после Add, Remove и Clear.','список.Count','List<int> stocks = new() { 2, 8, 0 };\nint positions = stocks.Count; // 3','Capacity — вместимость внутреннего хранилища, а Count — реальные элементы. Не используйте Capacity как число товаров.',api('system.collections.generic.list-1.count'),["products.Count","_products.Count"],['число элементов','количество позиций']),
 e('list-clear','List<T>.Clear()',collections,'Метод','Удаляет все элементы списка, сохраняя сам объект списка. После вызова Count равно 0.','список.Clear()','List<int> stocks = new() { 2, 8 };\nstocks.Clear(); // Count == 0','Очистка коллекции данных и очистка видимых строк интерфейса — разные действия. Не очищайте данные при простом обновлении представления.',api('system.collections.generic.list-1.clear'),[],['очистить список','удалить все элементы']),
 e('list-remove','List<T>.Remove()',collections,'Метод','Удаляет первое найденное вхождение элемента и возвращает true, если элемент был удалён.','список.Remove(элемент)','List<string> names = new() { "Мяч", "Ракетка" };\nbool removed = names.Remove("Мяч");','Поиск использует правила равенства элементов. Для собственного класса совпадение текста Name ещё не означает равенство двух экземпляров.',api('system.collections.generic.list-1.remove'),['Remove'],['удалить элемент','удаление по значению']),
 e('list-remove-at','List<T>.RemoveAt()',collections,'Метод','Удаляет элемент по индексу. Последующие элементы сдвигаются влево, а Count уменьшается.','список.RemoveAt(индекс)','List<string> names = new() { "Мяч", "Ракетка" };\nnames.RemoveAt(0); // остаётся Ракетка','Индекс должен быть от 0 до Count - 1. При последовательном удалении по индексам часто удобнее идти с конца списка.',api('system.collections.generic.list-1.removeat'),['RemoveAt'],['удаление по индексу']),
 e('list-contains','List<T>.Contains()',collections,'Метод','Проверяет наличие равного элемента в списке и возвращает bool. Для проверки по отдельному свойству нужен иной подход, например Any.','список.Contains(элемент)','List<string> names = new() { "Мяч", "Ракетка" };\nbool exists = names.Contains("Мяч");','Это поиск элемента целиком, а не поиск подстроки внутри каждого имени. Для регистра и других правил задавайте явную логику.',api('system.collections.generic.list-1.contains'),[],['есть в списке']),
 e('list-find','List<T>.Find()',collections,'Метод','Возвращает первый элемент, для которого предикат истинный, либо default(T), если совпадения нет.','список.Find(x => условие)','List<string> names = new() { "Мяч", "Ракетка" };\nstring? found = names.Find(name => name.StartsWith("Р"));','Для ссылочного типа отсутствие результата обычно означает null. Для int возвращённый 0 может совпасть с реальным элементом 0.',api('system.collections.generic.list-1.find'),['Find'],['найти элемент','поиск по условию']),
 e('list-exists','List<T>.Exists()',collections,'Метод','Проверяет, существует ли хотя бы один элемент списка, удовлетворяющий предикату. Возвращает bool.','список.Exists(x => условие)','List<int> stocks = new() { 2, 8, 0 };\nbool emptyExists = stocks.Exists(stock => stock == 0);','Exists не возвращает найденный элемент. В LINQ похожую задачу решает Any(predicate).',api('system.collections.generic.list-1.exists'),[],['проверить существование']),
 e('dictionary','Dictionary<TKey,TValue>',collections,'Тип','Хранит значения по уникальным ключам. Позволяет искать данные по коду или идентификатору без перебора всего списка.','Dictionary<ТипКлюча, ТипЗначения>','Dictionary<string, int> stocks = new();\nstocks["AB12"] = 8;\nint stock = stocks["AB12"];','Обращение по отсутствующему ключу выбрасывает исключение. Если отсутствие ожидаемо, используйте TryGetValue.',api('system.collections.generic.dictionary-2'),['Dictionary'],['словарь','ключ значение']),
 e('try-get-value','Dictionary.TryGetValue()',collections,'Метод','Пробует получить значение по ключу. Возвращает bool и записывает найденное значение либо default в out-параметр.','словарь.TryGetValue(ключ, out Тип значение)','Dictionary<string, int> stocks = new() { ["AB12"] = 8 };\nif (stocks.TryGetValue("AB12", out int stock))\n    Console.WriteLine(stock);','Проверяйте возвращённый bool. Сам по себе 0 в out-переменной не доказывает, что ключ найден.',api('system.collections.generic.dictionary-2.trygetvalue'),['TryGetValue'],['безопасный поиск по ключу']),
 e('hashset','HashSet<T>',collections,'Тип','Коллекция уникальных элементов. Add возвращает false, если равный элемент уже присутствует.','HashSet<Тип>','HashSet<string> codes = new(StringComparer.OrdinalIgnoreCase);\nbool first = codes.Add("AB12"); // true\nbool again = codes.Add("ab12"); // false','Порядок обхода не следует использовать как гарантированную сортировку. Правила уникальности задаёт comparer.',api('system.collections.generic.hashset-1'),['HashSet'],['множество','уникальные значения']),
 e('where','Enumerable.Where()',collections,'Метод LINQ','Отбирает элементы, для которых предикат возвращает true. Обычно создаёт отложенную последовательность без изменения источника.','источник.Where(x => условие)','int[] stocks = { 2, 8, 0 };\nvar low = stocks.Where(stock => stock <= 3);\nint[] snapshot = low.ToArray();','Требуется System.Linq. До перечисления или ToList/ToArray запрос обычно ещё не выполняет фильтрацию.',api('system.linq.enumerable.where'),['Where'],['фильтр','отбор элементов','LINQ']),
 e('select','Enumerable.Select()',collections,'Метод LINQ','Преобразует каждый элемент последовательности в новое значение. Число элементов при обычном Select не меняется.','источник.Select(x => выражение)','int[] stocks = { 2, 8, 0 };\nvar labels = stocks.Select(stock => $"{stock} шт.");','Select не фильтрует элементы: для этого используется Where. Чтобы получить коллекцию результата сразу, добавьте ToList или ToArray.',api('system.linq.enumerable.select'),['Select'],['проекция','преобразование коллекции']),
 e('order-by','OrderBy() и ThenBy()',collections,'Метод LINQ','OrderBy задаёт основную сортировку, ThenBy — дополнительную для элементов с одинаковым основным ключом. Источник не изменяется.','источник.OrderBy(x => ключ1).ThenBy(x => ключ2)','string[] names = { "Кеды", "Мяч", "Боты" };\nvar ordered = names.OrderBy(name => name.Length).ThenBy(name => name);','Повторный OrderBy начинает новую основную сортировку. Для следующего уровня используйте ThenBy; для убывания — OrderByDescending.',api('system.linq.enumerable.orderby'),['OrderBy','ThenBy'],['сортировка','упорядочить']),
 e('any','Enumerable.Any()',collections,'Метод LINQ','Проверяет наличие хотя бы одного элемента; перегрузка с предикатом проверяет наличие подходящего элемента.','источник.Any()\nисточник.Any(x => условие)','int[] stocks = { 2, 8, 0 };\nbool hasEmpty = stocks.Any(stock => stock == 0);','Any останавливает проверку, когда ответ уже известен. Для простой проверки существования не нужно сначала считать все элементы.',api('system.linq.enumerable.any'),['Any'],['хотя бы один','поиск дубликата']),
 e('first-default','Enumerable.FirstOrDefault()',collections,'Метод LINQ','Возвращает первый элемент или default(T), если подходящих элементов нет. Перегрузка позволяет передать условие поиска.','источник.FirstOrDefault(x => условие)','string[] names = { "Мяч", "Ракетка" };\nstring? found = names.FirstOrDefault(name => name.StartsWith("К"));','Для ссылочного типа проверьте результат на null. First() вместо FirstOrDefault() выбрасывает исключение, если элемента нет.',api('system.linq.enumerable.firstordefault'),['FirstOrDefault'],['первый элемент','результат или null']),
 e('sum','Enumerable.Sum()',collections,'Метод LINQ','Суммирует числовые элементы или значения, полученные селектором. Для пустой последовательности поддерживаемых обычных чисел сумма равна нулю.','источник.Sum()\nисточник.Sum(x => число)','int[] stocks = { 2, 8, 0 };\nint total = stocks.Sum(); // 10','Не путайте сумму остатков с Count. При суммировании больших целых возможна ошибка переполнения.',api('system.linq.enumerable.sum'),['Sum'],['сумма','накопление']),
 e('to-list','Enumerable.ToList()',collections,'Метод LINQ','Выполняет перечисление и сохраняет результат в новом List<T>. Полезен для фиксации результата отложенного запроса.','источник.ToList()','List<int> filtered = new[] { 2, 8, 0 }\n    .Where(stock => stock > 0).ToList();','Копируется список ссылок или значений, а не глубокие копии всех объектов. Изменение свойств ссылочного элемента может быть видно и в исходной коллекции.',api('system.linq.enumerable.tolist'),['ToList'],['материализация','копия списка']),

 e('try-catch','try, catch, finally',files,'Ключевое слово','try содержит операцию, способную выбросить исключение, catch обрабатывает ожидаемый тип ошибки, finally выполняет завершающие действия.','try { ... } catch (Тип ex) { ... } finally { ... }','try\n{\n    string text = System.IO.File.ReadAllText("tests.txt");\n}\ncatch (System.IO.IOException ex)\n{\n    Console.WriteLine(ex.Message);\n}','Не скрывайте все ошибки пустым catch. Неверный пользовательский ввод обычно удобнее обработать проверкой или TryParse до основной операции.',lang('language-reference/statements/exception-handling-statements'),['try','catch','finally'],['обработка исключений','ошибка выполнения']),
 e('throw','throw',files,'Ключевое слово','Создаёт или повторно передаёт исключение, когда метод не может выполнить свой контракт. Нормальное выполнение прерывается до подходящего обработчика.','throw new ТипИсключения("сообщение");','if (price <= 0m)\n    throw new ArgumentException("Цена должна быть положительной", nameof(price));','В catch запись throw; сохраняет исходное место исключения лучше, чем throw ex;. Не используйте исключение вместо обычного выбора ветки.',lang('language-reference/statements/exception-handling-statements'),['throw'],['выбросить исключение']),
 e('using-resource','using — освобождение ресурса',files,'Ключевое слово','Гарантирует освобождение IDisposable-объекта после выхода из блока или области объявления, включая выход по исключению.','using (Тип объект = ...) { ... }\nusing Тип объект = ...;','using System.IO.StreamReader reader = new("tests.txt");\nstring? firstLine = reader.ReadLine();','Это не директива подключения пространства имён. У using-объявления Dispose вызывается в конце содержащей области, у using-блока — после блока.',lang('language-reference/statements/using'),["using (ProductDetailsForm","using ProductDetailsForm","Dispose"],['Dispose','освобождение ресурсов','закрыть файл']),
 e('idisposable','IDisposable.Dispose()',files,'Интерфейс','Задаёт способ явно освободить удерживаемые ресурсы, например открытый файловый дескриптор. using вызывает Dispose автоматически.','объект.Dispose()','using var stream = new System.IO.MemoryStream();\nstream.WriteByte(42);','Dispose не означает немедленное уничтожение объекта сборщиком мусора. После освобождения ресурса объект обычно нельзя продолжать использовать.',api('system.idisposable'),['Dispose','IDisposable'],['жизненный цикл ресурса']),
 e('argument-exception','ArgumentException',files,'Исключение','Сообщает, что переданный аргумент недопустим для метода. В конструкторе помогает не допустить создание объекта с неверными данными.','new ArgumentException(сообщение, имяПараметра)','if (string.IsNullOrWhiteSpace(name))\n    throw new ArgumentException("Укажите название", nameof(name));','Если значение выходит за разрешённый диапазон, есть более специальный ArgumentOutOfRangeException. Форма должна показать понятное сообщение, а не аварийно завершиться.',api('system.argumentexception'),['ArgumentException'],['неверный аргумент','проверка конструктора']),
 e('invalid-operation','InvalidOperationException',files,'Исключение','Указывает, что операция недопустима при текущем состоянии объекта. Отличается от ошибки самого формата аргумента.','new InvalidOperationException(сообщение)','bool loaded = false;\nif (!loaded)\n    throw new InvalidOperationException("Сначала загрузите каталог");','Изменение List во время foreach тоже способно вызвать это исключение. Прочитайте сообщение и исправьте порядок операций.',api('system.invalidoperationexception'),['InvalidOperationException'],['неверное состояние']),
 e('file-exists','File.Exists()',files,'Метод','Проверяет наличие доступного файла по пути и возвращает bool. Не гарантирует, что следующая операция чтения удастся.','File.Exists(путь)','bool exists = System.IO.File.Exists("tests.txt");','Между проверкой и чтением файл может исчезнуть; права доступа тоже могут измениться. При реальном чтении всё равно учитывайте исключения.',api('system.io.file.exists'),["File.Exists"],['файл существует']),
 e('read-all-text','File.ReadAllText()',files,'Метод','Открывает текстовый файл, читает всё содержимое в строку и закрывает файл.','File.ReadAllText(путь)','string report = System.IO.File.ReadAllText("tests.txt");','Для очень больших файлов чтение целиком расходует много памяти. Относительный путь отсчитывается от рабочей папки процесса, не обязательно от папки исходников.',api('system.io.file.readalltext'),['ReadAllText'],['прочитать файл','чтение текста']),
 e('write-all-text','File.WriteAllText()',files,'Метод','Создаёт текстовый файл и записывает строку. Если файл уже существует, прежнее содержимое заменяется целиком.','File.WriteAllText(путь, текст)','System.IO.File.WriteAllText("tests.txt", "Ожидалось: 2; получилось: 2");','Для добавления к существующему отчёту нужен AppendAllText. Каталог назначения должен существовать и быть доступен для записи.',api('system.io.file.writealltext'),['WriteAllText'],['записать файл','сохранить отчёт','перезапись']),
 e('append-all-text','File.AppendAllText()',files,'Метод','Добавляет текст в конец файла, а при отсутствии файла создаёт его. Перевод строки сам по себе не добавляется.','File.AppendAllText(путь, текст)','System.IO.File.AppendAllText("tests.txt",\n    "Проверка пройдена" + Environment.NewLine);','AppendAllText сохраняет старые записи. Для нового отчёта с чистого листа используйте WriteAllText.',api('system.io.file.appendalltext'),['AppendAllText'],['дописать файл','журнал проверок']),
 e('path-combine','Path.Combine()',files,'Метод','Соединяет части пути с учётом разделителей платформы. Помогает не собирать путь вручную строковыми слешами.','Path.Combine(папка, имяФайла)','string path = System.IO.Path.Combine(\n    AppContext.BaseDirectory, "tests.txt");','Если последующий компонент является абсолютным путём, он может заменить предыдущие части. Combine не проверяет права и не делает произвольный пользовательский путь безопасным.',api('system.io.path.combine'),['Combine'],['составить путь','папка файла']),
 e('create-directory','Directory.CreateDirectory()',files,'Метод','Создаёт папку и недостающие промежуточные папки. Если папка уже существует, это не считается ошибкой само по себе.','Directory.CreateDirectory(путь)','System.IO.Directory.CreateDirectory("Reports");\nSystem.IO.File.WriteAllText(\n    System.IO.Path.Combine("Reports", "tests.txt"), "Проверка");','Метод не создаёт сам текстовый файл. Возможны ошибки неверного пути или отсутствия доступа.',api('system.io.directory.createdirectory'),['CreateDirectory'],['создать папку']),
 e('task','Task и Task<T>',files,'Тип','Представляют выполняющуюся или уже завершённую асинхронную операцию. Task<T> дополнительно предоставляет результат типа T после завершения.','Task\nTask<ТипРезультата>','async Task<string> ReadReportAsync()\n{\n    return await System.IO.File.ReadAllTextAsync("tests.txt");\n}','Task не обязательно соответствует отдельному потоку. Исключение асинхронной операции обычно наблюдают при await.',api('system.threading.tasks.task'),['Task'],['задача','асинхронный результат']),
 e('async-await','async и await',files,'Ключевое слово','async разрешает использовать await в методе, а await ожидает завершения операции без обязательной блокировки вызывающего потока.','async Task МетодAsync() { await операция; }','async Task<string> LoadAsync()\n{\n    string text = await System.IO.File.ReadAllTextAsync("tests.txt");\n    return text;\n}','async сам не переносит вычисления в фоновый поток. async void обычно оставляют обработчикам событий; обычные методы возвращают Task или Task<T>.',lang('asynchronous-programming/async-scenarios'),['async','await'],['асинхронность','не блокировать интерфейс']),
 e('cancellation','CancellationToken',files,'Тип','Передаёт запрос отмены операции. Отмена кооперативна: операция должна учитывать токен и корректно завершиться.','CancellationToken\nCancellationTokenSource.Cancel()','using var source = new System.Threading.CancellationTokenSource();\nsource.Cancel();\nbool cancelled = source.Token.IsCancellationRequested;','Запрос отмены не завершает произвольный поток принудительно. OperationCanceledException обрабатывают отдельно от настоящих ошибок операции.',api('system.threading.cancellationtoken'),['CancellationToken'],['отмена операции']),
 e('task-run','Task.Run()',files,'Метод','Планирует работу в пуле потоков. Подходит для достаточно длительных вычислений, которые не должны блокировать интерфейс.','await Task.Run(() => вычисление)','int result = await Task.Run(() =>\n{\n    int sum = 0;\n    for (int i = 0; i < 1000; i++) sum += i;\n    return sum;\n});','Пример размещается внутри async-метода. В фоновом коде нельзя напрямую менять элементы WinForms; для обычного асинхронного I/O обёртка Task.Run обычно не нужна.',api('system.threading.tasks.task.run'),["Task.Run"],['фоновое вычисление','пул потоков'])
];
